INSERT INTO public.periods (id,label_fr,label_en,description_fr,description_en,wikidata_id,wikipedia_title_fr,wikipedia_title_en,start_date,end_date,start_years_bp,end_years_bp,non_thematic) VALUES
('171fd59a-b152-4da6-8422-e51fb8ca15b2','Jeunesse à Nazareth','Early years in Nazareth','Les évangiles disent peu de choses de ces années passées en Galilée, où Jésus aurait exercé un métier d’artisan.','The gospels say little about these years spent in Galilee, where Jesus is said to have worked as a craftsman.',NULL,NULL,NULL,'4 BCE','0028',2029.82203969884,1998.82409308693,false),
('3fb2964d-de48-4f2a-875b-8769a91cbba9','Ministère de Jésus','Ministry of Jesus','Jésus prêche en Galilée puis en Judée, entouré de disciples ; la durée de cette prédication, d’un à trois ans, varie selon les évangiles.','Jesus preaches in Galilee and then Judaea, surrounded by disciples; the gospels give this preaching a length of one to three years.','Q749771','Ministère de Jésus','Ministry of Jesus','0028','0030',1998.82409308693,1996.82272416153,false),
('47391fb9-b687-47cf-b7c6-007cfe2de813','Premières communautés chrétiennes','First Christian communities','Les disciples, puis Paul de Tarse, diffusent le message de Jésus autour de la Méditerranée ; les évangiles sont mis par écrit.','The disciples, then Paul of Tarsus, spread the message of Jesus around the Mediterranean; the gospels are written down.',NULL,NULL,NULL,'0030','0100',1996.82272416153,1926.82409308693,false),
('2f14683f-3616-425a-92f3-81bdfa5c1cc6','Jeunesse princière à Kapilavastu','Princely youth in Kapilavastu','Selon la tradition, Siddhartha grandit dans le clan des Shakya, à l’abri du spectacle de la souffrance.','According to tradition, Siddhartha grows up in the Shakya clan, sheltered from the sight of suffering.',NULL,NULL,NULL,'563 BCE','534 BCE',2588.81177275838,2559.81245722108,false),
('b3232f0c-fd2c-41a7-b742-5c3a96d870ee','Ascèse et quête de l’Éveil','Asceticism and the quest for awakening','Devenu ascète errant, Siddhartha suit plusieurs maîtres et pratique des privations extrêmes avant de choisir une voie moyenne.','As a wandering ascetic, Siddhartha follows several teachers and practises extreme austerities before choosing a middle way.',NULL,NULL,NULL,'534 BCE','528 BCE',2559.81245722108,2553.81108829569,false),
('6b383777-95a7-4b40-ab09-7f91a4a300a0','Enseignement dans la plaine du Gange','Teaching in the Ganges plain','Le Bouddha parcourt les royaumes de Magadha et de Kosala, enseigne et fonde une communauté de moines et de moniales.','The Buddha travels through the kingdoms of Magadha and Kosala, teaching and founding a community of monks and nuns.',NULL,NULL,NULL,'528 BCE','483 BCE',2553.81108829569,2508.81451060917,false),
('00d6a23a-41c6-4d42-b88d-3311ac81ce66','Enfance et études de Newton','Newton’s childhood and studies','Élevé par sa grand-mère dans le Lincolnshire, Newton entre au Trinity College de Cambridge en 1661.','Raised by his grandmother in Lincolnshire, Newton enters Trinity College, Cambridge, in 1661.',NULL,NULL,NULL,'1643-01-04','1665',383.848049281314,361.854893908282,false),
('41cb45f7-0a7f-42e4-a92b-af1662795887','Années de découvertes à Woolsthorpe','Years of discovery at Woolsthorpe','Pendant la fermeture de Cambridge due à la peste, Newton pose les bases du calcul infinitésimal, de sa théorie des couleurs et de la gravitation.','While Cambridge is closed by the plague, Newton lays the foundations of calculus, of his theory of colours and of gravitation.',NULL,NULL,NULL,'1665','1667',361.854893908282,359.856262833676,false),
('a15bd693-4457-4e5e-a5d7-cc8a213a4cef','Newton professeur à Cambridge','Newton as professor at Cambridge','Newton enseigne les mathématiques, mène ses travaux d’optique et de mécanique et rédige les Principia.','Newton teaches mathematics, pursues his work on optics and mechanics and writes the Principia.',NULL,NULL,NULL,'1667','1696',359.856262833676,330.856947296372,false),
('3ec572b0-79f0-44bc-a7f3-46f20748d8a7','Newton à la Monnaie de Londres','Newton at the Royal Mint','Gardien puis maître de la Monnaie, Newton conduit la refonte des pièces anglaises tout en présidant la Royal Society.','As warden and then master of the Mint, Newton oversees the English recoinage while presiding over the Royal Society.',NULL,NULL,NULL,'1696','1727-03-31',330.856947296372,299.615331964408,false),
('44c9100b-6148-411f-823a-69cd088ce8c4','Jeunesse et études d’Einstein','Einstein’s youth and studies','Einstein grandit à Munich, quitte l’Allemagne à quinze ans et obtient son diplôme à l’École polytechnique de Zurich en 1900.','Einstein grows up in Munich, leaves Germany at fifteen and graduates from the Zurich Polytechnic in 1900.',NULL,NULL,NULL,'1879-03-14','1902',147.664613278576,124.86379192334,false),
('b4174d5c-c48e-4b23-9c2c-58424aa9332e','Einstein à l’office des brevets de Berne','Einstein at the Bern patent office','Employé comme expert technique, Einstein publie en 1905 ses articles sur les quanta de lumière, le mouvement brownien et la relativité restreinte.','Working as a technical examiner, Einstein publishes in 1905 his papers on light quanta, Brownian motion and special relativity.',NULL,NULL,NULL,'1902','1909',124.86379192334,117.863107460643,false),
('e3220e30-6214-4c45-a32a-5b7b831b86ff','Carrière universitaire d’Einstein en Europe','Einstein’s academic career in Europe','Professeur à Zurich, Prague puis Berlin, Einstein achève la relativité générale et devient mondialement célèbre.','A professor in Zurich, Prague and then Berlin, Einstein completes general relativity and becomes world famous.',NULL,NULL,NULL,'1909','1933',117.863107460643,93.8631074606434,false),
('b330a053-ee57-4ef8-94f9-19c7b117f471','Einstein en exil à Princeton','Einstein in exile at Princeton','Chassé par l’arrivée des nazis au pouvoir, Einstein s’installe aux États-Unis, cherche une théorie unifiée et s’engage pour la paix.','Driven out when the Nazis take power, Einstein settles in the United States, seeks a unified theory and campaigns for peace.',NULL,NULL,NULL,'1933','1955-04-18',93.8631074606434,71.5715263518138,false),
('dce67b6a-c990-489f-a99f-979032a6da18','Jeunesse de Hitler en Autriche','Hitler’s youth in Austria','Fils d’un douanier, Hitler échoue deux fois au concours des Beaux-Arts de Vienne, où il vit ensuite sans emploi stable.','The son of a customs official, Hitler twice fails the entrance examination of the Vienna Academy of Fine Arts, then lives there without steady work.',NULL,NULL,NULL,'1889-04-20','1913-05',137.561943874059,113.534565366188,false),
('004b49a1-6649-40f6-8cf3-b405d749e6a2','Hitler à Munich et dans la Grande Guerre','Hitler in Munich and the Great War','Installé à Munich, Hitler s’engage dans l’armée bavaroise en 1914 et sert comme estafette sur le front de l’Ouest.','Having moved to Munich, Hitler enlists in the Bavarian army in 1914 and serves as a dispatch runner on the Western Front.',NULL,NULL,NULL,'1913-05','1919-09',113.534565366188,107.199178644764,false),
('5cca0848-630e-43f5-be47-e0e83f4a3800','Hitler à la tête du parti nazi','Hitler at the head of the Nazi Party','Hitler rejoint un petit parti nationaliste munichois, en prend la direction et en fait, après la crise de 1929, la première force électorale d’Allemagne.','Hitler joins a small nationalist party in Munich, takes it over and, after the 1929 crisis, makes it the largest electoral force in Germany.',NULL,NULL,NULL,'1919-09','1933-01-30',107.199178644764,93.7837097878166,false),
('1840fe8f-edd3-4aa0-aeb5-84dc47da8072','Dictature de Hitler avant la guerre','Hitler’s dictatorship before the war','En quelques mois, Hitler supprime les libertés et les partis ; le régime persécute les Juifs, réarme et annexe l’Autriche puis les Sudètes.','Within months Hitler abolishes civil liberties and parties; the regime persecutes Jews, rearms and annexes Austria and then the Sudetenland.',NULL,NULL,NULL,'1933-01-30','1939-09-01',93.7837097878166,87.1991786447639,false),
('82796f9c-af44-4233-be6b-1117e3d52eb9','Hitler chef de guerre','Hitler as war leader','Hitler déclenche la guerre en Europe, dirige personnellement les opérations et ordonne l’extermination des Juifs d’Europe.','Hitler starts the war in Europe, directs operations in person and orders the extermination of the Jews of Europe.',NULL,NULL,NULL,'1939-09-01','1945-04-30',87.1991786447639,81.5373032169747,false),
('6dc9a1f3-1f1f-4b6a-afdf-5da98b79aa0d','Jeunesse de Truman dans le Missouri','Truman’s youth in Missouri','Truman grandit à Independence, travaille dans une banque puis exploite pendant dix ans la ferme familiale.','Truman grows up in Independence, works in a bank and then runs the family farm for ten years.',NULL,NULL,NULL,'1884-05-08','1917',142.511978097194,109.863107460643,false),
('f2322aa0-5e9d-403b-9b99-94a6fb24226f','Truman, de la Grande Guerre à la politique locale','Truman from the Great War to local politics','Capitaine d’artillerie en France, Truman ouvre ensuite une mercerie qui fait faillite, puis est élu juge administratif du comté de Jackson.','An artillery captain in France, Truman then opens a haberdashery that fails, and is elected a county judge of Jackson County.',NULL,NULL,NULL,'1917','1935-01-03',109.863107460643,91.8590006844627,false),
('b5a4e08d-62af-4a77-8501-579ee41f96b9','Truman sénateur du Missouri','Truman as senator from Missouri','Soutien du New Deal, Truman se fait connaître en présidant la commission qui contrôle les dépenses de guerre.','A supporter of the New Deal, Truman makes his name chairing the committee that scrutinises war spending.',NULL,NULL,NULL,'1935-01-03','1945-01-17',91.8590006844627,81.8193018480493,false),
('a0f7f685-62ef-45e5-b1d6-0b3103fbc90d','Présidence de Harry S. Truman','Presidency of Harry S. Truman','Truman termine la guerre, lance la politique d’endiguement et le plan Marshall, puis engage le pays en Corée.','Truman ends the war, launches containment and the Marshall Plan, then commits the country in Korea.','Q2824575','Présidence de Harry S. Truman','Presidency of Harry S. Truman','1945-04-12','1953-01-20',81.586584531143,73.8110882956879,true),
('2b1532ee-b0a1-4028-b6e8-b4fa19f7d738','Retraite de Truman à Independence','Truman’s retirement in Independence','Truman rédige ses mémoires et fonde sa bibliothèque présidentielle.','Truman writes his memoirs and founds his presidential library.',NULL,NULL,NULL,'1953-01-20','1972-12-26',73.8110882956879,53.8795345653662,false);
INSERT INTO public.events (id,label_fr,label_en,description_fr,description_en,wikidata_id,wikipedia_title_fr,wikipedia_title_en,date,date_years_bp) VALUES
('bc9373a8-b30a-4046-87fb-45a1d696a652','Baptême de Jésus','Baptism of Jesus','Selon les évangiles, Jésus est baptisé dans le Jourdain par Jean le Baptiste, ce qui ouvre sa vie publique.','According to the gospels, Jesus is baptised in the Jordan by John the Baptist, which opens his public life.','Q217048','Baptême du Christ','Baptism of Jesus','0028',1998.82409308693),
('5e05893b-ae79-460c-8796-b6021ef10f27','Conversion de Paul','Conversion of Paul','Persécuteur des premiers disciples, Paul de Tarse rallie le mouvement et devient son principal missionnaire auprès des non-Juifs ; la date est approximative.','A persecutor of the first disciples, Paul of Tarsus joins the movement and becomes its leading missionary to non-Jews; the date is approximate.','Q901397','Conversion de Paul','Conversion of Paul the Apostle','0034',1992.82272416153),
('e1402c65-7c5a-4f58-8d5a-a013153e48eb','Concile de Jérusalem','Council of Jerusalem','Les responsables du mouvement décident que les convertis non juifs ne sont pas tenus à la circoncision.','The leaders of the movement decide that non-Jewish converts are not required to be circumcised.','Q619950','Concile de Jérusalem','Council of Jerusalem','0049',1977.82203969884),
('66a3b06d-2a7f-4837-a6b5-7cc5a2812787','Naissance de Siddhartha à Lumbini','Birth of Siddhartha at Lumbini','La tradition situe la naissance du futur Bouddha à Lumbini, dans l’actuel Népal ; des historiens la placent environ quatre-vingts ans plus tard.','Tradition places the birth of the future Buddha at Lumbini, in present-day Nepal; some historians date it about eighty years later.',NULL,NULL,NULL,'563 BCE',2588.81177275838),
('b6f3c08e-4b39-47df-8969-77925fc370ff','Le Grand Départ','The Great Renunciation','Siddhartha quitte son palais, sa femme et son fils pour mener une vie d’ascète.','Siddhartha leaves his palace, his wife and his son to live as an ascetic.','Q73413583',NULL,'Great Renunciation','534 BCE',2559.81245722108),
('a57d84a6-0af1-44ff-b185-80ac404f2783','Éveil à Bodh-Gaya','Awakening at Bodh Gaya','Après une nuit de méditation sous un figuier, Siddhartha atteint l’Éveil et devient le Bouddha.','After a night of meditation under a fig tree, Siddhartha attains awakening and becomes the Buddha.',NULL,NULL,NULL,'528 BCE',2553.81108829569),
('66417f66-794d-49d4-8205-02bb66191a78','Premier sermon à Sarnath','First sermon at Sarnath','Près de Bénarès, le Bouddha expose les quatre nobles vérités à ses cinq premiers disciples.','Near Benares, the Buddha sets out the four noble truths to his first five disciples.',NULL,NULL,NULL,'528 BCE',2553.81108829569),
('5c1efb55-a211-4f3c-b517-037cca032bad','Mort du Bouddha à Kushinagar','Death of the Buddha at Kushinagar','Le Bouddha meurt à environ quatre-vingts ans ; ses disciples parlent de parinirvana, l’extinction complète.','The Buddha dies aged about eighty; his disciples speak of parinirvana, complete extinction.','Q111723540',NULL,NULL,'483 BCE',2508.81451060917),
('057ea60b-e225-4952-b855-00870439e1d3','Naissance d’Isaac Newton','Birth of Isaac Newton','Newton naît à Woolsthorpe, dans le Lincolnshire, le 25 décembre 1642 du calendrier julien alors en usage en Angleterre.','Newton is born at Woolsthorpe, Lincolnshire, on 25 December 1642 in the Julian calendar then used in England.',NULL,NULL,NULL,'1643-01-04',383.848049281314),
('ba492c9e-e1dd-432f-9a5f-60da4fd6df65','Télescope à réflexion de Newton','Newton’s reflecting telescope','Newton construit le premier télescope à miroir utilisable, qui évite les irisations des lunettes à lentilles.','Newton builds the first working mirror telescope, which avoids the colour fringes of lens telescopes.','Q7020022',NULL,'Newton''s reflector','1668',358.856947296372),
('7cfa79a0-84cb-422b-8bb3-2612f8dcd0b0','Newton titulaire de la chaire lucasienne','Newton appointed Lucasian Professor','À vingt-six ans, Newton succède à Isaac Barrow à la chaire de mathématiques de Cambridge.','Aged twenty-six, Newton succeeds Isaac Barrow in the Cambridge chair of mathematics.',NULL,NULL,NULL,'1669',357.854893908282),
('abd02931-6438-4f2c-a6f4-a1485fe0e8bf','Newton élu à la Royal Society','Newton elected to the Royal Society','Son télescope lui vaut d’être élu ; il présente la même année sa théorie de la lumière et des couleurs.','His telescope earns him election; the same year he presents his theory of light and colours.',NULL,NULL,NULL,'1672',354.856947296372),
('5f40645d-9fa8-4ade-baa3-2e01e71f57da','Newton président de la Royal Society','Newton president of the Royal Society','Newton est élu à la présidence de la société savante, qu’il conserve jusqu’à sa mort.','Newton is elected president of the learned society, a post he holds until his death.',NULL,NULL,NULL,'1703',323.859000684463),
('8391c918-8f76-4b1d-9bcf-2ff4ef105989','Opticks de Newton','Newton’s Opticks','Newton publie en anglais ses expériences sur la décomposition de la lumière blanche et la nature des couleurs.','Newton publishes in English his experiments on the decomposition of white light and the nature of colours.','Q74263','Opticks','Opticks','1704',322.859685147159),
('3b5a7e82-e754-4bbb-a2dd-4863ca246f72','Newton anobli par la reine Anne','Newton knighted by Queen Anne','La reine Anne fait Newton chevalier lors d’une visite à Cambridge.','Queen Anne knights Newton during a visit to Cambridge.',NULL,NULL,NULL,'1705-04-16',321.57015742642),
('f8a5d01a-99f4-475a-9e8c-fe5c2a3b07d3','Mort d’Isaac Newton','Death of Isaac Newton','Newton meurt à Kensington et est inhumé à l’abbaye de Westminster.','Newton dies at Kensington and is buried in Westminster Abbey.',NULL,NULL,NULL,'1727-03-31',299.615331964408),
('cdcbd73e-409c-41c6-83b6-f48c2fbfb64d','Naissance d’Albert Einstein','Birth of Albert Einstein','Einstein naît à Ulm, dans le royaume de Wurtemberg, dans une famille juive non pratiquante.','Einstein is born in Ulm, in the Kingdom of Württemberg, into a non-observant Jewish family.',NULL,NULL,NULL,'1879-03-14',147.664613278576),
('b451457d-2d65-4445-a45e-8bafb68cfc89','L’éclipse de 1919 confirme la relativité générale','The 1919 eclipse confirms general relativity','Les expéditions d’Arthur Eddington mesurent la déviation de la lumière des étoiles par le Soleil, comme le prévoit la théorie.','Arthur Eddington’s expeditions measure the bending of starlight by the Sun, as the theory predicts.','Q65041294',NULL,'Eddington experiment','1919-05-29',107.459274469541),
('1ad9f168-95ec-41f8-9d75-cf6525587848','Prix Nobel de physique d’Einstein','Einstein’s Nobel Prize in Physics','Le prix de l’année 1921 lui est attribué pour son explication de l’effet photoélectrique, et non pour la relativité.','The prize for 1921 is awarded to him for his explanation of the photoelectric effect, not for relativity.',NULL,NULL,NULL,'1922-11-09',104.009582477755),
('2381297d-a64f-4171-9341-e6a566103bc9','Lettre d’Einstein à Roosevelt','Einstein’s letter to Roosevelt','Rédigée avec Leó Szilárd, la lettre avertit le président américain qu’une bombe à uranium est possible et que l’Allemagne pourrait la construire.','Drafted with Leó Szilárd, the letter warns the US president that a uranium bomb is possible and that Germany might build one.','Q714081','Lettre Einstein-Szilárd','Einstein–Szilard letter','1939-08-02',87.2813141683778),
('d9d60af7-f6dd-4a9e-84f3-a87e502103f9','Einstein devient citoyen américain','Einstein becomes a US citizen','Einstein prête serment à Trenton, tout en conservant sa nationalité suisse.','Einstein takes the oath in Trenton while keeping his Swiss citizenship.',NULL,NULL,NULL,'1940-10-01',86.1149897330595),
('483de104-ab36-4193-aef4-606788e8309d','Mort d’Albert Einstein','Death of Albert Einstein','Einstein meurt à Princeton quelques jours après avoir signé un manifeste contre les armes nucléaires.','Einstein dies in Princeton a few days after signing a manifesto against nuclear weapons.',NULL,NULL,NULL,'1955-04-18',71.5715263518138),
('ddfc25db-f6f5-4f57-9f1c-70cec6470476','Naissance d’Adolf Hitler','Birth of Adolf Hitler','Hitler naît à Braunau am Inn, ville autrichienne à la frontière de la Bavière.','Hitler is born in Braunau am Inn, an Austrian town on the Bavarian border.',NULL,NULL,NULL,'1889-04-20',137.561943874059),
('69db05e1-e4eb-4d3b-8081-708cd064b2a8','Putsch de la Brasserie','Beer Hall Putsch','Hitler tente de prendre le pouvoir à Munich ; le coup de force échoue le lendemain et lui vaut la prison.','Hitler attempts to seize power in Munich; the coup fails the next day and lands him in prison.','Q36749','Putsch de la Brasserie','Beer Hall Putsch','1923-11-08',103.013004791239),
('2640d87c-71c0-4826-b884-cfb5b7dd4a97','Publication de Mein Kampf','Publication of Mein Kampf','Rédigé en prison, le premier volume expose l’antisémitisme de Hitler et son projet d’expansion vers l’Est.','Written in prison, the first volume sets out Hitler’s antisemitism and his plan for expansion to the East.','Q48244','Mein Kampf','Mein Kampf','1925-07-18',101.321013004791),
('ac1b4e1a-286a-455e-a42f-a45678b2ebd9','Incendie du Reichstag','Reichstag fire','L’incendie du Parlement sert de prétexte à un décret qui suspend les libertés et permet l’arrestation des opposants.','The burning of the parliament building serves as the pretext for a decree suspending civil liberties and allowing the arrest of opponents.','Q153992','Incendie du Reichstag','Reichstag fire','1933-02-27',93.7070499657769),
('481e81dd-685f-4c51-97c0-dee32afb91f1','Nuit des longs couteaux','Night of the Long Knives','Hitler fait assassiner les chefs de la SA et plusieurs adversaires conservateurs, s’assurant le soutien de l’armée.','Hitler has the SA leaders and several conservative opponents murdered, securing the support of the army.','Q130783','Nuit des longs couteaux','Night of the Long Knives','1934-06-30',92.3709787816564),
('2bb11259-6abe-401c-86cb-cb1737cbb0b0','Hitler devient Führer','Hitler becomes Führer','À la mort du président Hindenburg, Hitler cumule les fonctions de chancelier et de chef de l’État.','On the death of President Hindenburg, Hitler combines the offices of chancellor and head of state.',NULL,NULL,NULL,'1934-08-02',92.280629705681),
('c1936e91-c0ff-4f7e-9060-155ad9038b42','Lois de Nuremberg','Nuremberg Laws','Les Juifs allemands sont privés de leur citoyenneté ; les mariages entre Juifs et non-Juifs sont interdits.','German Jews are stripped of their citizenship; marriages between Jews and non-Jews are banned.','Q27906','Lois de Nuremberg','Nuremberg Laws','1935-09-15',91.160848733744),
('cf84b98c-9c2e-434e-b945-ad7600b515c3','Nuit de Cristal','Kristallnacht','Dans toute l’Allemagne, synagogues et commerces juifs sont détruits ; près de trente mille Juifs sont envoyés en camp de concentration.','Across Germany, synagogues and Jewish shops are destroyed; nearly thirty thousand Jews are sent to concentration camps.','Q36756','Nuit de Cristal','Kristallnacht','1938-11-09',88.009582477755),
('97da4dad-7dc6-41d9-98d3-225e0387e34b','Attentat du 20 juillet 1944','20 July plot','Une bombe posée par le colonel von Stauffenberg blesse légèrement Hitler ; la répression fait des milliers de victimes.','A bomb planted by Colonel von Stauffenberg slightly wounds Hitler; thousands are killed in the reprisals.','Q105570','Complot du 20 juillet 1944','20 July plot','1944-07-20',82.3148528405202),
('0277b0da-5735-4e4c-9e30-f219a6dbb22e','Naissance de Harry S. Truman','Birth of Harry S. Truman','Truman naît à Lamar, dans le Missouri, dans une famille de fermiers.','Truman is born in Lamar, Missouri, into a farming family.',NULL,NULL,NULL,'1884-05-08',142.511978097194),
('7b578525-5bf0-45e7-965e-9f3ec6562936','Truman devient président','Truman becomes president','Vice-président depuis moins de trois mois, Truman prête serment quelques heures après la mort de Franklin Roosevelt.','Vice president for less than three months, Truman is sworn in a few hours after the death of Franklin Roosevelt.',NULL,NULL,NULL,'1945-04-12',81.586584531143),
('9706a7b0-b18c-4f36-a6c8-02e0c615dd47','Conférence de Potsdam','Potsdam Conference','Truman, Staline et Churchill, remplacé par Attlee, fixent le sort de l’Allemagne vaincue et somment le Japon de capituler.','Truman, Stalin and Churchill, replaced by Attlee, settle the fate of defeated Germany and call on Japan to surrender.','Q151187','Conférence de Potsdam','Potsdam Conference','1945-07-17',81.3237508555784),
('2d3422d6-f000-4413-8e62-13b4ffeed792','Truman reconnaît l’État d’Israël','Truman recognises the State of Israel','Les États-Unis reconnaissent le nouvel État quelques minutes après sa proclamation.','The United States recognises the new state minutes after its proclamation.',NULL,NULL,NULL,'1948-05-14',78.498288843258),
('d76ec111-4fef-4511-991e-1206be1f8c92','Déségrégation des forces armées américaines','Desegregation of the US armed forces','Par décret, Truman impose l’égalité de traitement dans l’armée, sans distinction de race.','By executive order, Truman requires equal treatment in the military regardless of race.','Q5419908','Executive Order 9981','Executive Order 9981','1948-07-26',78.2984257357974),
('8ef016f8-5bd8-4f5d-8da2-61d9887f873b','Réélection de Truman','Truman’s re-election','Donné battu par les sondages et la presse, Truman l’emporte sur le républicain Thomas Dewey.','Written off by the polls and the press, Truman defeats the Republican Thomas Dewey.','Q568973','Élection présidentielle américaine de 1948','1948 United States presidential election','1948-11-02',78.0273785078713),
('c0851630-8774-4728-a7d0-340c81c7c220','Truman renvoie le général MacArthur','Truman dismisses General MacArthur','Le commandant en Corée, qui réclamait publiquement d’étendre la guerre à la Chine, est relevé de ses fonctions.','The commander in Korea, who publicly called for extending the war to China, is relieved of his command.','Q1344952',NULL,'Relief of Douglas MacArthur','1951-04-11',75.5906913073238),
('14a15b09-e1ab-497b-b58e-200179577d70','Mort de Harry S. Truman','Death of Harry S. Truman','Truman meurt à Kansas City à quatre-vingt-huit ans.','Truman dies in Kansas City aged eighty-eight.',NULL,NULL,NULL,'1972-12-26',53.8795345653662);
